// ── FUNÇÃO 1: REMOVE ASTERISCOS ──
function removerAsteriscos(texto) {
  if (!texto) return texto;
  return texto
    .replace(/\*\*/g, '')
    .replace(/\*/g, '');
}

// ── FUNÇÃO 2: CONVERTE LISTA DE PONTO PARA HÍFEN ──
function converterListaParaHifen(texto) {
  if (!texto) return texto;

  let textoLimpo = removerAsteriscos(texto);

  // Converte "1. ", "2. ", "3. " para "1- ", "2- ", "3- "
  let textoConvertido = textoLimpo.replace(
    /(\d+)\.\s+(?=[A-Za-zÀ-Úà-ú])/g,
    '$1- '
  );

  return textoConvertido;
}

// ── FUNÇÃO 3: QUEBRA APÓS PONTUAÇÃO (. ! ? : ) ──
function quebrarAposPontuacao(texto) {
  if (!texto) return texto;

  // Quebra após ., !, ?, : quando seguido por espaço
  let textoComQuebras = texto
    .replace(/([.!?:])\s+(?=[A-ZÀ-Úa-zà-ú\d])/g, '$1\n')
    .replace(/(\d+-\s+)/g, '\n$1'); // Garante que lista fique em nova linha

  // Remove quebra duplicada no início
  textoComQuebras = textoComQuebras.replace(/^\n+/, '');

  return textoComQuebras;
}

// ── FUNÇÃO 4: LIMPEZA FINAL ──
function limpezaFinal(texto) {
  if (!texto) return texto;

  return texto
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/\n\n\n/g, '\n\n')
    .replace(/^\s+|\s+$/g, '');
}

// ── FUNÇÕES ADICIONAIS ──

function formatarDataHora(dataISO, incluirDiaSemana = true) {
  if (!dataISO) return '';
  try {
    const d = new Date(dataISO);
    const dias = ['Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'];
    const meses = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 
                   'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];

    const diaSemana = dias[d.getDay()];
    const dia = d.getDate();
    const mes = meses[d.getMonth()];
    const hora = d.getHours().toString().padStart(2, '0');
    const minuto = d.getMinutes().toString().padStart(2, '0');

    if (incluirDiaSemana) {
      return `${diaSemana}, ${dia} de ${mes} às ${hora}:${minuto}h`;
    }
    return `${dia}/${d.getMonth()+1} ${hora}:${minuto}h`;
  } catch(e) {
    return dataISO;
  }
}

function separador() {
  return '─'.repeat(30);
}

// ── FORMATAÇÃO PRINCIPAL ──

let textoFormatado = '';

// 1. CONFIRMAÇÃO DE AGENDAMENTO
if (acao === 'criar_evento' && dados.dateTime_inicio) {
