  textoFormatado += `${separador()}\n\n`;
  textoFormatado += `📅 Data: ${formatarDataHora(dados.dateTime_inicio)}\n`;

  if (duracao) textoFormatado += `⏱️ Duração: ${duracao}\n`;
  if (local) textoFormatado += `📍 Local: ${local}\n`;
  if (nome) textoFormatado += `👤 Cliente: ${nome}\n`;
  if (valor) textoFormatado += `💰 Valor: ${valor}\n`;
